In Nestjs project (or any other project using decorator), using this eslint-config will make wrong indent in parameter decorator and property decorator.

```ts
import { Body, Headers, Query, Inject, Get, Post } from '@nestjs/common'

export class Foo {
  @Inject()
  a: any

  @Inject()
  b: any

  constructor(
    @Headers()
    @Query()
    q: any,
    @Headers()
    h: any,
    @Body()
    b: any
  ) {
    console.log(q)
    console.log(h)
    console.log(b)
  }

  get(
    @Query() q: any,
    @Headers() h: any
  ) {
    console.log(q)
    console.log(h)
  }
}

```

Code above will finally format to code below, whose parameter and property indents are wrong.

```ts
import { Body, Headers, Query, Inject } from '@nestjs/common'

export class Foo {
  @Inject()
    a: any

  @Inject()
    b: any

  constructor(
  @Headers()
  @Query()
    q: any,
    @Headers()
    h: any,
    @Body()
    b: any
  ) {
    console.log(q)
    console.log(h)
    console.log(b)
  }

  get(
  @Query() q: any,
    @Headers() h: any
  ) {
    console.log(q)
    console.log(h)
  }
}
```

